// utils/templates/{template}/{Template}Template.ts
// Template Method — squelette d'algorithme pour {Template}

export abstract class {Template}Template {
  // ── Template method — FINAL, ne pas surcharger ─────────────────
  // Le squelette de l'algorithme est défini ici, ne change jamais
  async execute(input: unknown): Promise<unknown[]> {
    this.validate(input)
    const parsed    = await this.parse(input)
    const processed = this.process(parsed)
    this.onComplete(processed.length)
    return processed
  }

  // ── Étapes ABSTRAITES — doivent être implémentées ──────────────
  protected abstract validate(input: unknown): void
  protected abstract parse(input: unknown): Promise<unknown>
  protected abstract process(data: unknown): unknown[]

  // ── Étapes OPTIONNELLES — peuvent être surchargées ─────────────
  protected onComplete(count: number): void {
    console.log(`[{Template}] Traitement terminé : ${count} éléments`)
  }
}

// Implémentation concrète A (ex: CSV)
export class {Template}TemplateA extends {Template}Template {
  protected validate(input: unknown): void {
    // Ajoute ici la validation spécifique au format A
    // Exemple : if (!String(input).endsWith('.csv')) throw new Error(...)
  }

  protected async parse(input: unknown): Promise<unknown> {
    // Ajoute ici le parsing spécifique au format A
    return input
  }

  protected process(data: unknown): unknown[] {
    // Ajoute ici le traitement des données parsées
    return [data]
  }
}

// Implémentation concrète B (ex: JSON)
export class {Template}TemplateB extends {Template}Template {
  protected validate(input: unknown): void {
    // Validation spécifique au format B
  }

  protected async parse(input: unknown): Promise<unknown> {
    // Parsing spécifique au format B
    return input
  }

  protected process(data: unknown): unknown[] {
    return Array.isArray(data) ? data : [data]
  }

  // Surcharge optionnelle
  protected onComplete(count: number): void {
    console.log(`[{Template}B] ${count} éléments importés avec succès`)
  }
}

// Factory — instancie la bonne implémentation
export type {Template}Format = 'formatA' | 'formatB'

export const create{Template}Template = (format: {Template}Format): {Template}Template => {
  const templates: Record<{Template}Format, new () => {Template}Template> = {
    formatA: {Template}TemplateA,
    formatB: {Template}TemplateB
  }
  return new templates[format]()
}

// composables/{template}/use{Template}.ts
import { create{Template}Template, type {Template}Format } from '~/utils/templates/{template}/{Template}Template'

export const use{Template} = () => {
  const execute = async (input: unknown, format: {Template}Format): Promise<unknown[]> => {
    // La factory choisit la bonne implémentation — le squelette reste le même
    const template = create{Template}Template(format)
    return template.execute(input)
  }

  const executeFormatA = (input: unknown) => execute(input, 'formatA')
  const executeFormatB = (input: unknown) => execute(input, 'formatB')

  return { execute, executeFormatA, executeFormatB }
}

// tests/utils/templates/{template}/{Template}Template.spec.ts
import { describe, it, expect, vi } from 'vitest'
import {
  {Template}TemplateA,
  {Template}TemplateB,
  create{Template}Template
} from '~/utils/templates/{template}/{Template}Template'

describe('{Template}Template', () => {

  describe('{Template}TemplateA', () => {
    it('execute() appelle validate, parse, process dans l\'ordre', async () => {
      const t       = new {Template}TemplateA()
      const validate = vi.spyOn(t as any, 'validate')
      const parse    = vi.spyOn(t as any, 'parse')
      const process  = vi.spyOn(t as any, 'process')
      await t.execute('input')
      expect(validate).toHaveBeenCalled()
      expect(parse).toHaveBeenCalled()
      expect(process).toHaveBeenCalled()
    })

    it('execute() retourne un tableau', async () => {
      const t      = new {Template}TemplateA()
      const result = await t.execute('input')
      expect(Array.isArray(result)).toBe(true)
    })
  })

  describe('{Template}TemplateB', () => {
    it('execute() retourne un tableau', async () => {
      const t      = new {Template}TemplateB()
      const result = await t.execute(['item1', 'item2'])
      expect(Array.isArray(result)).toBe(true)
    })
  })

  describe('create{Template}Template()', () => {
    it('retourne une instance {Template}TemplateA pour formatA', () => {
      expect(create{Template}Template('formatA')).toBeInstanceOf({Template}TemplateA)
    })

    it('retourne une instance {Template}TemplateB pour formatB', () => {
      expect(create{Template}Template('formatB')).toBeInstanceOf({Template}TemplateB)
    })

    it('les deux formats utilisent le même squelette (execute)', () => {
      const a = create{Template}Template('formatA')
      const b = create{Template}Template('formatB')
      expect(typeof a.execute).toBe('function')
      expect(typeof b.execute).toBe('function')
    })
  })

})
